import {readAuthResponse} from './auth-response.js';
const signup=document.body.dataset.page==='signup';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const target=new URLSearchParams(location.search).get('next')||'/index.html';
const next=/^\/?[a-z][a-z0-9-]*\.html(?:\?[^#]*)?$/.test(target)&&!/^\/?(?:login|signup|signin)\.html/.test(target)?target:'/index.html';
const moon='<path d="M20.8 13.1A9 9 0 0 1 10.9 3.2 9 9 0 1 0 20.8 13.1Z"/>';
const field=(name,label,type,autocomplete)=>`<label class="auth-field" for="${name}"><span>${label}</span><input id="${name}" name="${name}" type="${type}" autocomplete="${autocomplete}" required ${name==='password'&&signup?'minlength="8" maxlength="128"':''} aria-describedby="error-${name}"><small id="error-${name}"></small></label>`;
document.body.innerHTML=`<header class="auth-top"><a class="auth-brand" href="login.html"><span>c</span>campus.</a><button id="theme-toggle" class="theme-toggle" type="button" role="switch" aria-label="Dark mode" aria-checked="false"><svg class="ico" viewBox="0 0 24 24" aria-hidden="true">${moon}</svg><span class="theme-toggle-label">Dark mode</span></button></header><main class="auth-container"><section class="auth-intro"><span class="eyebrow">YOUR UNIVERSITY DAY, TOGETHER</span><h1>A clearer day<br>starts here.</h1><p>One place for your classes, study plans, and everything in between.</p><div class="auth-benefits"><span>01 <strong>Know what’s next.</strong></span><span>02 <strong>Make time to study.</strong></span><span>03 <strong>Find your rhythm.</strong></span></div></section><section class="auth-panel"><div class="eyebrow">${signup?'MAKE YOURSELF AT HOME':'WELCOME BACK'}</div><h2>${signup?'Create your account.':'Sign in to Campus.'}</h2><p>${signup?'Use your email and choose a password.':'Enter your credentials to open your workspace.'}</p><form id="auth-form" novalidate><div id="auth-error" role="alert" hidden></div>${signup?field('full_name','Full name','text','name'):''}${field('email','Email address','email','email')}${field('password','Password','password',signup?'new-password':'current-password')}${signup?field('confirm_password','Confirm password','password','new-password'):''}<label class="show-password"><input id="show-password" type="checkbox">Show password</label><button class="auth-submit" type="submit">${signup?'Create account':'Sign in'} <span aria-hidden="true">→</span></button></form><p class="auth-switch">${signup?'Already have an account?':'New to Campus?'} <a href="${signup?'login':'signup'}.html?next=${encodeURIComponent(next)}">${signup?'Sign in':'Create an account'}</a></p><small class="auth-private">Your workspace opens only after you sign in.</small></section></main>`;
window.CampusTheme?.bindToggle();document.querySelector('#show-password').onchange=e=>document.querySelectorAll('input[name*="password"]').forEach(input=>input.type=e.target.checked?'text':'password');
const form=document.querySelector('#auth-form');form.onsubmit=async event=>{event.preventDefault();const values=Object.fromEntries(new FormData(form)),errors={};if(signup&&!values.full_name.trim())errors.full_name='Enter your full name.';if(!values.email.trim())errors.email='Enter your email.';else if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(values.email))errors.email='Enter a valid email.';if(!values.password)errors.password='Enter your password.';else if(signup&&(values.password.length<8||values.password.length>128))errors.password='Use 8–128 characters.';if(signup&&values.password!==values.confirm_password)errors.confirm_password='Passwords do not match.';form.querySelectorAll('small').forEach(el=>el.textContent='');form.querySelectorAll('[aria-invalid]').forEach(el=>el.removeAttribute('aria-invalid'));const alert=document.querySelector('#auth-error');alert.hidden=true;if(Object.keys(errors).length){for(const [name,message] of Object.entries(errors)){form.elements.namedItem(name).setAttribute('aria-invalid','true');document.querySelector('#error-'+name).textContent=message}form.querySelector('[aria-invalid]').focus();return}const button=form.querySelector('[type="submit"]');button.disabled=true;button.textContent=signup?'Creating account…':'Signing in…';try{const response=await fetch('/api/auth/'+(signup?'signup':'login'),{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify({full_name:values.full_name,email:values.email.trim(),password:values.password})});const result=await readAuthResponse(response);if(!response.ok)throw Error(result.error||'Please try again.');form.reset();location.replace(next)}catch(error){alert.hidden=false;alert.textContent=error.message||'Could not connect. Keep the Campus server running and try again.';button.disabled=false;button.innerHTML=(signup?'Create account':'Sign in')+' <span aria-hidden="true">→</span>'}};
